const embeddingResult = $('Generate Message Embedding').first()?.json;
const message = $('When Executed by Another Workflow').first()?.json?.message || '';

// Embeddings come from the backend (local all-mpnet-base-v2, 768-dim) via
// POST /api/knowledge/embed -> { success, data: { embedding: [...] } }.
// Same model for query + storage is required for cosine similarity to work.
let embedding = null;
if (embeddingResult && Array.isArray(embeddingResult.data?.embedding) && embeddingResult.data.embedding.length > 0) {
  embedding = embeddingResult.data.embedding;
} else if (embeddingResult && Array.isArray(embeddingResult.embedding) && embeddingResult.embedding.length > 0) {
  embedding = embeddingResult.embedding;
} else if (embeddingResult && Array.isArray(embeddingResult) && embeddingResult.length > 0) {
  embedding = embeddingResult[0];
}

const hasValid = Boolean(embedding && Array.isArray(embedding) && embedding.length === 768);

// n8n's Postgres node splits queryReplacement on commas, which shatters a
// 768-dim vector ("[0.1,0.2,...]") into hundreds of fragments. Send it
// base64-encoded (no commas) to POST /api/knowledge/search/hybrid instead.
let embeddingB64 = '';
if (hasValid) {
  try {
    embeddingB64 = Buffer.from(JSON.stringify(embedding), 'utf8').toString('base64');
  } catch (e) {
    embeddingB64 = '';
  }
}

return [{
  json: {
    embedding_b64: embeddingB64,
    message_text: message,
    has_vector: hasValid
  }
}];

const items = $input.all();
let knowledge = [];
const firstItem = items[0]?.json || {};

if (firstItem.knowledge && Array.isArray(firstItem.knowledge)) {
  knowledge = firstItem.knowledge.map(function(hit) {
    if (!hit || !hit.chunk_text) return null;
    if (typeof hit.similarity !== 'number' && typeof hit.score === 'number') hit.similarity = hit.score;
    return hit;
  }).filter(Boolean);
} else if (firstItem.success && Array.isArray(firstItem.data)) {
  knowledge = firstItem.data.map(hit => {
    const chunk_text = hit.chunk_text || '';
    const metadata = hit.metadata || {};
    return {
      chunk_text,
      metadata,
      source: typeof metadata === 'string' ? metadata : (hit.source || metadata.title || metadata.document_title || ''),
      similarity: typeof hit.similarity === 'number' ? hit.similarity : (typeof hit.score === 'number' ? hit.score : null)
    };
  }).filter(k => !!k.chunk_text);
} else if (firstItem.result && Array.isArray(firstItem.result)) {
  knowledge = firstItem.result.map(hit => {
    const payload = hit.payload || {};
    const chunk_text = payload.chunk_text || payload.pageContent || '';
    const metadata = payload.metadata || payload || {};
    return {
      chunk_text,
      metadata,
      source: typeof metadata === 'string' ? metadata : (metadata.title || metadata.document_title || ''),
      similarity: typeof hit.similarity === 'number' ? hit.similarity : (typeof hit.score === 'number' ? hit.score : null)
    };
  }).filter(k => !!k.chunk_text);
} else {
  knowledge = items
    .map(item => {
      const doc = item.json.document || item.json || {};
      const chunk_text = doc.pageContent || doc.chunk_text || item.json.chunk_text || '';
      if (!chunk_text) return null;
      const metadata = doc.metadata || item.json.metadata || {};
      return {
        chunk_text,
        metadata,
        source: typeof metadata === 'string' ? metadata : (metadata.title || metadata.document_title || ''),
        similarity: item.json.similarity ?? item.json.score ?? null,
        score: item.json.score ?? null
      };
    })
    .filter(Boolean);
}

return [{ json: { knowledge } }];
